tools.definitionText:
{
  "name": "crop",
  "description": "Crop a rectangular region from an image. Saves the cropped result to disk and returns a preview.\n\nCoordinates are normalized (0-1000), same as grounding output.",
  "inputSchema": {
    "properties": {
      "image_path": {
        "description": "Absolute path to the source image file",
        "type": "string"
      },
      "box": {
        "description": "Crop region as [x1, y1, x2, y2] in normalized coordinates (0-1000)",
        "items": {
          "type": "integer"
        },
        "maxItems": 4,
        "minItems": 4,
        "type": "array"
      },
      "output_path": {
        "description": "Where to save the cropped image. Defaults to {stem}_cropped.{ext} next to the\noriginal.",
        "type": "string"
      }
    },
    "required": [
      "image_path",
      "box"
    ],
    "type": "object"
  }
}

{
  "name": "draw_bbox",
  "description": "Draw bounding boxes on an image. Saves the annotated result to disk and returns a preview.\n\nCoordinates are normalized (0-1000), same as grounding output.",
  "inputSchema": {
    "properties": {
      "image_path": {
        "description": "Absolute path to the source image file",
        "type": "string"
      },
      "bboxes": {
        "description": "Boxes to draw. Each item has bbox=[x1, y1, x2, y2] in normalized coordinates\n(0-1000), an optional label above the box, and an optional hex color such as\n'#FF0000'. Omitted colors cycle through the default palette.",
        "items": {
          "properties": {
            "bbox": {
              "items": {
                "type": "integer"
              },
              "maxItems": 4,
              "minItems": 4,
              "type": "array"
            },
            "label": {
              "type": "string"
            },
            "color": {
              "type": "string"
            }
          },
          "required": [
            "bbox"
          ],
          "type": "object"
        },
        "type": "array"
      },
      "output_path": {
        "description": "Where to save the annotated image. Defaults to {stem}_annotated.{ext} next to\nthe original.",
        "type": "string"
      }
    },
    "required": [
      "image_path",
      "bboxes"
    ],
    "type": "object"
  }
}

{
  "name": "media_info",
  "description": "Read full metadata from a video/audio file via ffprobe: container format, duration, file size,\n\noverall bitrate, chapters, and every stream — video (codec/profile, resolution, aspect ratio,\nfps, pixel format, bitrate, frame count, rotation, color space), audio (codec, sample rate,\nchannels/layout, bitrate), subtitles, and per-stream language/disposition. Use this before any\nediting/clipping task to learn the source properties; it reads only metadata, so it is fast even\non huge files.",
  "inputSchema": {
    "properties": {
      "path": {
        "description": "Absolute path to the media file (video or audio)",
        "type": "string"
      },
      "raw": {
        "default": false,
        "description": "Also return the raw ffprobe JSON (format + streams + chapters) for fields not covered\nby the summary. Default: false",
        "type": "boolean"
      }
    },
    "required": [
      "path"
    ],
    "type": "object"
  }
}

{
  "name": "read_image",
  "description": "Read an image with model-optimized dynamic resolution. Automatically resizes to fit the target\n\nmodel's patch grid, balancing resolution and detail preservation. Returns the resized image for\nmodel consumption.",
  "inputSchema": {
    "properties": {
      "image_path": {
        "description": "Absolute path to the image file",
        "type": "string"
      },
      "budget": {
        "default": "normal",
        "description": "Resolution preset: small (~512×512), normal (~1024×1024), large (~1448×1448).",
        "enum": [
          "small",
          "normal",
          "large"
        ],
        "type": "string"
      }
    },
    "required": [
      "image_path"
    ],
    "type": "object"
  }
}

{
  "name": "read_video",
  "description": "Extract frames from a video file with dynamic resolution and FPS. When fps=0 (default),\n\nautomatically selects the best sampling rate based on video duration. Resolution is\nautomatically adjusted to fit the patch grid. For full source properties (codec, bitrate, native\nfps, rotation, VFR, audio tracks) — and before any clip/edit task — run media_info first.",
  "inputSchema": {
    "properties": {
      "video_path": {
        "description": "Absolute path to the video file",
        "type": "string"
      },
      "fps": {
        "default": 0,
        "description": "Sampling FPS. 0 = auto-detect based on duration (recommended). Default: 0",
        "type": "number"
      },
      "max_frames": {
        "default": 600,
        "description": "Maximum frames to extract (capped at 600). Actual count may be lower or stripped\ndepending on video length and response size limits.",
        "type": "integer"
      },
      "budget": {
        "default": "normal",
        "description": "Per-frame resolution preset: small (~288×288), normal (~512×512), large\n(~1024×1024).",
        "enum": [
          "small",
          "normal",
          "large"
        ],
        "type": "string"
      },
      "start_time": {
        "description": "Start time — seconds or a clock string ('MM:SS'/'HH:MM:SS'). Default: 0\n(beginning).",
        "type": [
          "number",
          "string"
        ]
      },
      "end_time": {
        "description": "End time — seconds or a clock string ('MM:SS'/'HH:MM:SS'). Default: end of video.",
        "type": [
          "number",
          "string"
        ]
      }
    },
    "required": [
      "video_path"
    ],
    "type": "object"
  }
}

{
  "name": "save_view",
  "description": "Materialize one or more views of a source as standalone image FILES and return their paths (+\n\npreviews). For a document (PDF/SVG/XPS, and PPTX/DOCX/XLSX/LaTeX via conversion), pass `pages`\n(a range like '1', '1-5', '2,4,7') to render those pages/slides; for a video, pass `times` (a\nlist of seconds) for those frames. Use this to turn document pages or video frames into image\nfiles you can then feed to crop / draw_bbox / grounding / ocr / image_search / segmentation.",
  "inputSchema": {
    "properties": {
      "file_path": {
        "description": "Absolute path to the source document or video.",
        "type": "string"
      },
      "pages": {
        "description": "Page range for documents, e.g. '1', '1-5', '2,4,7'. Default: '1'. Ignored for video.",
        "type": "string"
      },
      "times": {
        "description": "Timestamps for video frames — seconds (52, 58.5) or a clock string\n('MM:SS'/'HH:MM:SS'). Required for video. Ignored for docs.",
        "items": {
          "type": [
            "number",
            "string"
          ]
        },
        "type": "array"
      },
      "dpi": {
        "description": "Render resolution for document pages (default 200). Ignored for video (native).",
        "type": "integer"
      },
      "budget": {
        "default": "normal",
        "description": "Resolution of the returned previews (the saved files are always full/native).",
        "enum": [
          "small",
          "normal",
          "large"
        ],
        "type": "string"
      },
      "output_dir": {
        "description": "Directory to write the images to. Default: next to the source file.",
        "type": "string"
      }
    },
    "required": [
      "file_path"
    ],
    "type": "object"
  }
}

{
  "name": "visualize",
  "description": "Visualize any supported file for model consumption. Renders documents (PDF, DOCX, PPTX, XLSX,\n\nCSV), code files (syntax-highlighted), SVG, DrawIO diagrams, subtitles (SRT/VTT), NIfTI medical\nvolumes, images, and videos as visual output. Automatically detects file type and applies the\nappropriate renderer.",
  "inputSchema": {
    "properties": {
      "file_path": {
        "description": "Absolute path to the file to visualize.",
        "type": "string"
      },
      "pages": {
        "description": "Page range for multi-page documents (e.g. '1-5', '3', '1,3,5-8'). 1-based. Default:\nfirst 20 pages.",
        "type": "string"
      },
      "budget": {
        "default": "large",
        "description": "Resolution preset per page/image: small (~512x512), normal (~1024x1024), large\n(~1448x1448).",
        "enum": [
          "small",
          "normal",
          "large"
        ],
        "type": "string"
      },
      "max_pages": {
        "default": 20,
        "description": "Maximum number of pages to render (default 20).",
        "type": "integer"
      }
    },
    "required": [
      "file_path"
    ],
    "type": "object"
  }
}

{
  "name": "grounding",
  "description": "Detect and locate objects in an image using a vision-language model. Returns bounding box\n\ncoordinates mapped to original image pixel dimensions. Optionally draws boxes on the image and\nreturns the annotated image.",
  "inputSchema": {
    "properties": {
      "image_path": {
        "description": "Absolute path to the image file",
        "type": "string"
      },
      "prompt": {
        "description": "What to detect (e.g., 'all cats', 'the red car', 'every person')",
        "type": "string"
      },
      "model": {
        "description": "Model id override. Defaults to QWEN_MM_API_VL_MODEL, then 'qwen3.7-plus'.",
        "type": "string"
      },
      "return_img": {
        "default": false,
        "description": "Return annotated image with bounding boxes drawn",
        "type": "boolean"
      },
      "api_key": {
        "description": "API key override; otherwise selected by endpoint.",
        "type": "string"
      },
      "base_url": {
        "description": "API base URL (defaults to DASHSCOPE_BASE_URL)",
        "type": "string"
      }
    },
    "required": [
      "image_path",
      "prompt"
    ],
    "type": "object"
  }
}

{
  "name": "ocr",
  "description": "Extract text from an image using a vision-language model. Supports printed text, handwriting,\n\ndocuments, signs, and more. Returns the recognized text content.",
  "inputSchema": {
    "properties": {
      "image_path": {
        "description": "Absolute path to the image file",
        "type": "string"
      },
      "prompt": {
        "description": "Custom OCR instruction. Default extracts all visible text. Override to focus on\nspecific regions or languages.",
        "type": "string"
      },
      "model": {
        "description": "Model id override. Defaults to QWEN_MM_API_VL_MODEL, then 'qwen3.7-plus'.",
        "type": "string"
      },
      "api_key": {
        "description": "API key override; otherwise selected by endpoint.",
        "type": "string"
      },
      "base_url": {
        "description": "API base URL (defaults to DASHSCOPE_BASE_URL)",
        "type": "string"
      }
    },
    "required": [
      "image_path"
    ],
    "type": "object"
  }
}

{
  "name": "omni_asr",
  "description": "Transcribe all speech in an audio/video file into ONE continuous plain-text string, with no\n\ntimestamps, using the Qwen-Omni model. For timestamps use omni_asr_timestamped; for speaker\nlabels use omni_multi_speaker_asr. A local file travels inline, where the endpoint caps a media\nitem at 10 MB of base64, so the audio is downmixed to 16 kHz mono and MP3-compressed at a\nduration-fitted bitrate when needed — good for roughly 55 min. For longer media pass an\nhttp(s)/OSS URL or transcribe in parts.",
  "inputSchema": {
    "properties": {
      "file_path": {
        "description": "Absolute path to a local audio/video file, or an http(s)/OSS URL.",
        "type": "string"
      },
      "language": {
        "description": "Spoken-language hint (zh, en, ja, …). Auto-detected if omitted.",
        "type": "string"
      },
      "model": {
        "description": "Omni model id override. Defaults to QWEN_MM_API_OMNI_MODEL, then qwen3.5-omni-plus.",
        "type": "string"
      },
      "api_key": {
        "description": "API key override; otherwise selected by endpoint.",
        "type": "string"
      },
      "base_url": {
        "description": "OpenAI-compatible base URL override.",
        "type": "string"
      },
      "dry_run": {
        "default": false,
        "description": "Return the request that would be sent, without calling the API.",
        "type": "boolean"
      }
    },
    "required": [
      "file_path"
    ],
    "type": "object"
  }
}

{
  "name": "omni_asr_timestamped",
  "description": "Transcribe speech with controllable-granularity timestamps (sentence- or word-level) using the\n\nQwen-Omni model. Returns segments with start/end seconds plus an SRT rendering. A local file\ntravels inline, where the endpoint caps a media item at 10 MB of base64, so the audio is\ndownmixed to 16 kHz mono and MP3-compressed at a duration-fitted bitrate when needed — good for\nroughly 55 min. For longer media pass an http(s)/OSS URL or transcribe in parts.",
  "inputSchema": {
    "properties": {
      "file_path": {
        "description": "Absolute path to a local audio/video file, or an http(s)/OSS URL.",
        "type": "string"
      },
      "granularity": {
        "default": "sentence",
        "description": "Timestamp granularity: 'sentence' (default) or 'word'.",
        "enum": [
          "sentence",
          "word"
        ],
        "type": "string"
      },
      "format": {
        "default": "json",
        "description": "Primary output: 'json' (default) or 'srt'.",
        "enum": [
          "json",
          "srt"
        ],
        "type": "string"
      },
      "language": {
        "description": "Spoken-language hint (zh, en, ja, …). Auto-detected if omitted.",
        "type": "string"
      },
      "model": {
        "description": "Omni model id override. Defaults to QWEN_MM_API_OMNI_MODEL, then qwen3.5-omni-plus.",
        "type": "string"
      },
      "api_key": {
        "description": "API key override; otherwise selected by endpoint.",
        "type": "string"
      },
      "base_url": {
        "description": "OpenAI-compatible base URL override.",
        "type": "string"
      },
      "dry_run": {
        "default": false,
        "description": "Return the request that would be sent, without calling the API.",
        "type": "boolean"
      }
    },
    "required": [
      "file_path"
    ],
    "type": "object"
  }
}

{
  "name": "omni_av_caption",
  "description": "Produce a detailed Markdown report of an audio/video using the Qwen-Omni model (reads both the\n\nvideo frames and the audio track): a timestamped storyline, all visible text, a speaker-\nattributed transcript, plus flags for content inappropriate for minors with a compliance-alert\ntable and a final safety assessment. A local file is uploaded inline, where the endpoint caps a\nmedia item at 10 MB of base64, so it is transcoded to fit — about 9 min at the default 1 fps /\n448² sampling. A longer local video is delivered another way automatically: uploaded to OSS when\nOSS_* is configured (no size limit), else split into sampled frames plus its full audio track.\nPassing an http(s)/OSS URL skips all of that (fetched and sampled server-side); for hour-scale\nvideo use video-memory. Use dry_run=true to preview the request payload without calling.",
  "inputSchema": {
    "properties": {
      "file_path": {
        "description": "Absolute path to a local audio/video file, or an http(s)/OSS URL.",
        "type": "string"
      },
      "fps": {
        "description": "Video sampling fps (default 1.0). Higher = finer temporal detail, more tokens, and a\nlarger upload — which shortens the maximum uploadable length.",
        "type": "number"
      },
      "max_pixels": {
        "description": "Per-frame pixel budget (default 200704 ≈ 448²).",
        "type": "integer"
      },
      "model": {
        "description": "Omni model id override. Defaults to QWEN_MM_API_OMNI_MODEL, then qwen3.5-omni-plus.",
        "type": "string"
      },
      "api_key": {
        "description": "API key override; otherwise selected by endpoint.",
        "type": "string"
      },
      "base_url": {
        "description": "OpenAI-compatible base URL override.",
        "type": "string"
      },
      "dry_run": {
        "default": false,
        "description": "Return the request that would be sent, without calling the API.",
        "type": "boolean"
      }
    },
    "required": [
      "file_path"
    ],
    "type": "object"
  }
}

{
  "name": "omni_av_counting",
  "description": "Count how many times a specified event/object/action occurs in an audio/video, returning the\n\ntotal count and the timestamp of each occurrence, using the Qwen-Omni model (reads frames +\naudio). A local file is uploaded inline, where the endpoint caps a media item at 10 MB of\nbase64, so it is transcoded to fit — about 9 min at the default 1 fps / 448² sampling (less at a\nhigher fps). A longer local video is delivered another way automatically: uploaded to OSS when\nOSS_* is configured (no size limit), else split into sampled frames plus its full audio track —\nat which point the frame spacing bounds how finely occurrences can be separated. Passing an\nhttp(s)/OSS URL keeps full sampling (fetched server-side), as does counting over a trimmed clip.",
  "inputSchema": {
    "properties": {
      "file_path": {
        "description": "Absolute path to a local audio/video file, or an http(s)/OSS URL.",
        "type": "string"
      },
      "target": {
        "description": "What to count, in natural language (e.g. 'times a car passes', 'goals scored', 'the\nword yes').",
        "type": "string"
      },
      "fps": {
        "description": "Video sampling fps (default 1.0). Raise for fast/frequent events — at the cost of a\nlarger upload, which shortens the maximum uploadable length.",
        "type": "number"
      },
      "max_pixels": {
        "description": "Per-frame pixel budget (default 200704 ≈ 448²).",
        "type": "integer"
      },
      "model": {
        "description": "Omni model id override. Defaults to QWEN_MM_API_OMNI_MODEL, then qwen3.5-omni-plus.",
        "type": "string"
      },
      "api_key": {
        "description": "API key override; otherwise selected by endpoint.",
        "type": "string"
      },
      "base_url": {
        "description": "OpenAI-compatible base URL override.",
        "type": "string"
      },
      "dry_run": {
        "default": false,
        "description": "Return the request that would be sent, without calling the API.",
        "type": "boolean"
      }
    },
    "required": [
      "file_path",
      "target"
    ],
    "type": "object"
  }
}

{
  "name": "omni_av_grounding",
  "description": "Temporal grounding: given a text query, locate the time segment(s) in an audio/video where it\n\noccurs, returning start/end seconds per match, using the Qwen-Omni model (reads frames + audio).\nThis is temporal (WHEN) localization — for spatial (WHERE in a frame) use core's grounding tool.\nA local file is uploaded inline, where the endpoint caps a media item at 10 MB of base64, so it\nis transcoded to fit — about 9 min at the default 1 fps / 448² sampling. A longer local video is\ndelivered another way automatically: uploaded to OSS when OSS_* is configured (no size limit),\nelse split into sampled frames plus its full audio track — at which point the frame spacing\nbounds visual timestamp precision (the audio timeline stays continuous). Passing an http(s)/OSS\nURL keeps full sampling (fetched server-side), as does grounding within a trimmed clip.",
  "inputSchema": {
    "properties": {
      "file_path": {
        "description": "Absolute path to a local audio/video file, or an http(s)/OSS URL.",
        "type": "string"
      },
      "query": {
        "description": "What to locate, in natural language (e.g. 'the goal celebration', 'when the speaker\nmentions pricing').",
        "type": "string"
      },
      "top_k": {
        "description": "Max number of matching segments to return (default: all found).",
        "type": "integer"
      },
      "fps": {
        "description": "Video sampling fps (default 1.0).",
        "type": "number"
      },
      "max_pixels": {
        "description": "Per-frame pixel budget (default 200704 ≈ 448²).",
        "type": "integer"
      },
      "model": {
        "description": "Omni model id override. Defaults to QWEN_MM_API_OMNI_MODEL, then qwen3.5-omni-plus.",
        "type": "string"
      },
      "api_key": {
        "description": "API key override; otherwise selected by endpoint.",
        "type": "string"
      },
      "base_url": {
        "description": "OpenAI-compatible base URL override.",
        "type": "string"
      },
      "dry_run": {
        "default": false,
        "description": "Return the request that would be sent, without calling the API.",
        "type": "boolean"
      }
    },
    "required": [
      "file_path",
      "query"
    ],
    "type": "object"
  }
}

{
  "name": "omni_multi_speaker_asr",
  "description": "Transcribe multi-speaker speech with speaker diarization: distinguishes and labels different\n\nspeakers, with start/end timestamps per segment, using the Qwen-Omni model. Returns diarized\nsegments plus an SRT rendering with speaker tags. A local file travels inline, where the\nendpoint caps a media item at 10 MB of base64, so the audio is downmixed to 16 kHz mono and\nMP3-compressed at a duration-fitted bitrate when needed — good for roughly 55 min. For longer\nmedia pass an http(s)/OSS URL or transcribe in parts.",
  "inputSchema": {
    "properties": {
      "file_path": {
        "description": "Absolute path to a local audio/video file, or an http(s)/OSS URL.",
        "type": "string"
      },
      "num_speakers": {
        "description": "Expected number of speakers, if known — a hint to guide diarization.",
        "type": "integer"
      },
      "format": {
        "default": "json",
        "description": "Primary output: 'json' (default) or 'srt'.",
        "enum": [
          "json",
          "srt"
        ],
        "type": "string"
      },
      "language": {
        "description": "Spoken-language hint (zh, en, ja, …). Auto-detected if omitted.",
        "type": "string"
      },
      "model": {
        "description": "Omni model id override. Defaults to QWEN_MM_API_OMNI_MODEL, then qwen3.5-omni-plus.",
        "type": "string"
      },
      "api_key": {
        "description": "API key override; otherwise selected by endpoint.",
        "type": "string"
      },
      "base_url": {
        "description": "OpenAI-compatible base URL override.",
        "type": "string"
      },
      "dry_run": {
        "default": false,
        "description": "Return the request that would be sent, without calling the API.",
        "type": "boolean"
      }
    },
    "required": [
      "file_path"
    ],
    "type": "object"
  }
}

{
  "name": "omni_music_caption",
  "description": "Analyze a music track and return structured tags (genre, moods, instruments, key, time\n\nsignature, vocal profile) plus a dense English caption suitable as a music-generation prompt,\nusing the Qwen-Omni model. Whole-track global analysis — NO timestamps or per-section breakdown.\nExtracts the audio track if given a video. An audio file that fits the endpoint's inline cap (10\nMB of base64) is sent untouched; a longer one is downmixed to 16 kHz mono MP3 to fit, which\ncosts some fidelity — pass an http(s)/OSS URL to avoid that.",
  "inputSchema": {
    "properties": {
      "file_path": {
        "description": "Absolute path to a local music audio/video file, or an http(s)/OSS URL.",
        "type": "string"
      },
      "model": {
        "description": "Omni model id override. Defaults to QWEN_MM_API_OMNI_MODEL, then qwen3.5-omni-plus.",
        "type": "string"
      },
      "api_key": {
        "description": "API key override; otherwise selected by endpoint.",
        "type": "string"
      },
      "base_url": {
        "description": "OpenAI-compatible base URL override.",
        "type": "string"
      },
      "dry_run": {
        "default": false,
        "description": "Return the request that would be sent, without calling the API.",
        "type": "boolean"
      }
    },
    "required": [
      "file_path"
    ],
    "type": "object"
  }
}

{
  "name": "segmentation",
  "description": "Segment objects in an image using a SAM3 server. Provide a text prompt describing what to\n\nsegment. Returns mask metadata and a visualization image with masks overlaid.",
  "inputSchema": {
    "properties": {
      "image_path": {
        "description": "Absolute path to the image file",
        "type": "string"
      },
      "prompt": {
        "description": "What to segment (e.g., 'the cat', 'blue car', 'all people')",
        "type": "string"
      },
      "server": {
        "description": "SAM3 server URL (defaults to SAM3_SERVER_URL env var)",
        "type": "string"
      }
    },
    "required": [
      "image_path",
      "prompt"
    ],
    "type": "object"
  }
}

{
  "name": "transcribe_audio",
  "description": "Transcribe speech from an audio or video file using DashScope Qwen3-ASR (27 languages, automatic\n\nlanguage detection). Extracts audio automatically from video files. Supports time range\nselection. Returns timestamped subtitles in SRT, plain text, or raw JSON format. Long files are\nautomatically chunked into segments for processing.",
