{
  "name": "vision_chat",
  "description": "Chat about images and videos via an OpenAI-compatible endpoint. Local videos are\n\nsampled into inline frames, so per request keep ≤ 250 items total (frames + images) and fps =\nframes / duration within [0.1, 10] — set video_max_frames to the video's length; for videos over\n~40 min use read_video instead. Remote video URLs are handled server-side. When OSS is\nconfigured (OSS_AK/OSS_SK/OSS_ENDPOINT/OSS_BUCKET) a local video is uploaded and sampled server-\nside instead, lifting the inline frame cap (still bounded by the model's server-side video-\nduration limit, e.g. 2 h for qwen3.7-plus). Use dry_run=true to preview the request payload\nwithout calling.",
  "inputSchema": {
    "properties": {
      "model": {
        "description": "Model id override. Defaults to QWEN_MM_API_VL_MODEL, then 'qwen3.7-plus'.",
        "type": "string"
      },
      "text": {
        "default": "Describe the visual content.",
        "description": "Text prompt (default: 'Describe the visual content.')",
        "type": "string"
      },
      "images": {
        "description": "Image URLs, data URLs, or local file paths",
        "items": {
          "type": "string"
        },
        "type": "array"
      },
