      },
      "temperature": {
        "description": "Sampling temperature",
        "type": "number"
      },
      "dry_run": {
        "default": false,
        "description": "If true, return the request payload without calling the endpoint",
        "type": "boolean"
      },
      "vl_high_resolution_images": {
