{
  "name": "enumerate_events",
  "description": "Enumerate ALL matching event instances in time order — built for COUNTING and 'how many times /\n\nlist every occurrence' questions. Unlike search_nodes (top-k best matches), this returns every\nnode above a similarity threshold, deduplicated and sorted by start time, in a compact format.\nProtocol for counting: 1) Call this with a descriptive statement of the target event. 2) Review\nthe time-ordered list; merge adjacent entries that describe the same real occurrence. 3) Verify\nborderline or ambiguous entries with read_video at their time ranges. 4) If the expected count\nseems higher than returned matches, retry with lower min_cosine and also try alternative\nphrasings of the event. Never count from a single top-10 search — recurring events are spread\nacross the whole video.",
  "inputSchema": {
    "properties": {
      "video_path": {
        "description": "Path to the video file. Memory auto-loaded from <video_path>.memory/",
        "type": "string"
      },
      "query": {
        "description": "Descriptive statement of the recurring event to enumerate (NOT a question). e.g. 'the\nplayer drinks wine from a gourd to restore health'.",
        "type": "string"
      },
      "min_cosine": {
        "default": 0.5,
        "description": "Minimum cosine similarity to keep a match (default 0.5). Lower it (e.g. 0.4) if\nyou suspect instances are missing; raise it (e.g. 0.6) if results contain many false\npositives.",
        "type": "number"
      },
      "max_results": {
        "default": 120,
        "description": "Maximum matches to return (cap 300).",
        "type": "integer"
      },
      "node_types": {
        "description": "Node types to enumerate (default ['event']). Use ['entity'] to enumerate\nobjects/people.",
        "items": {
          "type": "string"
        },
        "type": "array"
      }
    },
    "required": [
      "query"
    ],
    "type": "object"
  }
}

{
  "name": "get_macro_events",
