        "description": "Path to the video file. Memory auto-loaded from <video_path>.memory/",
        "type": "string"
      },
      "super_id": {
        "description": "Filter by super event ID, e.g. 'super_01'. Optional — omit to list all.",
        "type": "string"
      },
      "macro_ids": {
        "description": "List of specific macro IDs to retrieve, e.g. ['macro_0001', 'macro_0002'].",
        "items": {
          "type": "string"
        },
        "type": "array"
      }
    },
    "type": "object"
  }
}

