{
  "name": "search_nodes",
  "description": "Semantic search over Entity and Event nodes by embedding similarity (excludes OCRText — use\n\nsearch_ocr_text for on-screen text). Returns top-k results with relevance scores and ego-graph\ncontext. When to use: You need to find specific events, actions, or entities but don't know\nwhich macro to look at. Query Construction Guide: Write a DESCRIPTIVE STATEMENT about the target\nevent, NOT a question — the embedding matches event descriptions, not questions. Extract key\nentities and actions from the question (person names, action types, objects). Extract SHARED\ninformation from all options — keywords/phrases that appear across multiple options are the most\nreliable retrieval signal. EXCLUDE speculative differing details from options — if options\ndisagree on a specific detail (e.g., different numbers, different names), do NOT pick one;\ninstead describe the event type neutrally. Good: 'A player scores with an alley-oop dunk' —\ndescriptive, captures the shared event type. Bad: 'Which player scored the alley-oop?' —\nquestion format, poor match with event descriptions. Good: 'A foul is committed on a specific\nplayer by an opposing player, leading to free throws' — captures shared info from options (foul\n+ free throws) while staying neutral on the differing detail. Bad: 'Australia No. 7 fouled' —\npicks one specific option's detail, may mislead if wrong.",
  "inputSchema": {
    "properties": {
      "video_path": {
        "description": "Path to the video file. Memory auto-loaded from <video_path>.memory/",
        "type": "string"
      },
      "query": {
        "description": "Descriptive statement for semantic search (NOT a question). Combine key entities,\nactions, and shared option info into a complete sentence.",
        "type": "string"
      },
      "top_k": {
        "default": 10,
        "description": "Number of results to return (default: 10).",
        "type": "integer"
      },
      "node_types": {
        "description": "Filter by node type (lowercase). Valid values: 'event', 'entity',\n'on_screen_text'. e.g. ['event'], ['entity'].",
        "items": {
          "type": "string"
        },
        "type": "array"
      }
    },
    "required": [
      "query"
    ],
    "type": "object"
  }
}

{
  "name": "search_ocr_text",
  "description": "Semantic search over OCR text nodes only (on-screen text: scores, names, graphics, jersey\n\nnumbers, broadcast overlays). When to use: Question asks about on-screen information (scores,\nplayer stats, quarter info, jersey names/numbers, broadcast graphics). Do NOT use search_nodes\nfor these — OCR text is excluded from search_nodes.",
  "inputSchema": {
    "properties": {
      "video_path": {
        "description": "Path to the video file. Memory auto-loaded from <video_path>.memory/",
        "type": "string"
      },
      "query": {
        "description": "Search text, e.g. 'scoreboard', 'third quarter score', 'jersey number'.",
        "type": "string"
      },
      "top_k": {
        "default": 10,
        "description": "Number of results to return (default: 10).",
        "type": "integer"
      }
    },
    "required": [
      "query"
    ],
    "type": "object"
  }
}

{
  "name": "get_memory_overview",
  "description": "The vocabulary a retrieval plan is written from: the cast of people (person_id, name,\n\nappearance, and also_heard_as for anyone still unnamed) and the COMPLETE directory of semantic\nfact keys. Read this before plan_and_search — fact keys are an exact lookup, so a plan that\nnames none comes back with no facts. One call covers every later question about the same video.\n`scene_env_available` only says a scene container exists; ask for the items with\nplan_and_search(include_scene=True).",
