        "type": "string"
      }
    },
    "type": "object"
  }
}

{
  "name": "get_memory_status",
  "description": "Does a memory exist, is it COMPLETE, and does this video even need one? Call this before\n\nanything else: it tells you whether to build, resume an interrupted build, watch the video\ndirectly instead, or start querying. An interrupted build leaves a library that looks normal but\nis truncated, so the extracted-clip count is checked against the slice plan. When no memory\nexists it also reports the source video's `duration_min` and a `next_step` that applies the\nlength routing — short videos are answered by watch_and_answer without building anything.",
  "inputSchema": {
    "properties": {
      "video_path": {
        "description": "Absolute path to the source video; memory is read from <video_path>.memory/.",
        "type": "string"
      },
      "namespace": {
        "description": "Memory name. Pass video_path too when MEM_LOCAL_DIR is unset; otherwise the\nmemory is read from the configured shared root.",
        "type": "string"
      }
    },
    "type": "object"
  }
}

