{
  "name": "plan_and_search",
  "description": "Run ONE retrieval from a plan you decide, fusing the memory containers: people, stable facts,\n\nmoments and (on request) environment, plus a ready-to-read evidence text and the clips worth re-\nwatching. **This does not answer the question — it returns evidence for you to reason over.**\nCall get_memory_overview first: naming the right person_ids, fact keys and query angles is what\nmakes the recall precise, and the keys are an exact lookup. Use this for open-ended questions;\nfor a targeted one go straight to the matching tool (search_dialogue, search_facts,\nget_person_dialogue, get_timeline, …).",
  "inputSchema": {
    "properties": {
      "video_path": {
        "description": "Absolute path to the source video; memory is read from <video_path>.memory/.",
        "type": "string"
      },
      "namespace": {
        "description": "Memory name. Pass video_path too when MEM_LOCAL_DIR is unset; otherwise the\nmemory is read from the configured shared root.",
        "type": "string"
      },
      "question": {
        "default": "",
        "description": "The question you are trying to answer.",
        "type": "string"
      },
      "people": {
        "description": "person_ids whose dossier and moments are relevant, e.g. ['P001']. Take them from\nget_memory_overview. A person whose name is still null may carry `also_heard_as` — that\nis how a name someone says maps onto an anonymous id.",
        "items": {
          "type": "string"
        },
        "type": "array"
      },
      "fact_keys": {
        "description": "Semantic keys to pull, e.g. ['Matthew/role']. EXACT lookup — pick them from\nget_memory_overview's semantic_key_directory. Name none and no facts come back; to find\nfacts by content rather than by key, use search_facts.",
        "items": {
          "type": "string"
        },
        "type": "array"
      },
      "queries": {
        "description": "Descriptive statements (not questions) to search moments with — 'someone offers to\nbring an umbrella', not 'who brought an umbrella?'. Several angles beat one long query.\nThese also decide which clips come back in suggested_replay_idxs, so describe what to\nlook for.",
        "items": {
          "type": "string"
        },
        "type": "array"
      },
      "time_ranges": {
        "description": "Optional [[start_sec, end_sec], ...] if the question concerns a time span.",
        "items": {
          "items": {
            "type": "number"
          },
          "type": "array"
        },
        "type": "array"
      },
      "include_scene": {
        "default": false,
        "description": "Also recall environment/layout items. Turn it on for 'where is X / what is in\nthe room' questions — it is off by default because recalling scene for every question\nmeasured net-negative, so it is a deliberate pick rather than a freebie.",
        "type": "boolean"
      },
      "top_k": {
        "default": 5,
        "description": "Maximum number of matching results to return.",
        "maximum": 20,
        "minimum": 1,
        "type": "integer"
      }
    },
    "type": "object"
  }
}

tools.description:
Re-watch source clips with audio when stored memory cannot settle a question. The Omni model

answers from what it sees and hears. Watches up to the configured replay limit per call;
requires an Omni model endpoint.

tools.definitionText:
{
  "name": "replay_and_answer",
  "description": "Re-watch source clips with audio when stored memory cannot settle a question. The Omni model\n\nanswers from what it sees and hears. Watches up to the configured replay limit per call;\nrequires an Omni model endpoint.",
  "inputSchema": {
    "properties": {
      "video_path": {
        "description": "Absolute path to the source video; memory is read from <video_path>.memory/.",
        "type": "string"
      },
      "namespace": {
        "description": "Memory name. Pass video_path too when MEM_LOCAL_DIR is unset; otherwise the\nmemory is read from the configured shared root.",
        "type": "string"
      },
      "question": {
        "description": "What to determine from watching the clips.",
        "type": "string"
      },
      "idxs": {
        "description": "Clip indices to re-watch, such as suggested_replay_idxs from plan_and_search or idxs\nfrom search_dialogue/get_timeline. Select the most promising clips; entries beyond the\nconfigured replay limit are returned in dropped_idxs.",
        "items": {
          "type": "integer"
        },
        "type": "array"
      },
      "evidence": {
        "default": "",
        "description": "Optional text context to give the model alongside the clips.",
        "type": "string"
      },
      "model": {
        "description": "Omni model for this call. Leave unset to use the configured default. It can differ\nfrom the model used to build the memory.",
        "type": "string"
      }
    },
    "required": [
      "question",
      "idxs"
    ],
    "type": "object"
  }
}

{
  "name": "search_dialogue",
  "description": "Search spoken lines and get them back WITH the speaker attached (person_id + resolved name). Use\n\nit when the question is about who said what, or to find the moment a topic was discussed. Unlike\na standalone ASR index, every line here is already bound to a person that persists across the\nwhole video.",
  "inputSchema": {
    "properties": {
      "video_path": {
        "description": "Absolute path to the source video; memory is read from <video_path>.memory/.",
        "type": "string"
      },
      "namespace": {
        "description": "Memory name. Pass video_path too when MEM_LOCAL_DIR is unset; otherwise the\nmemory is read from the configured shared root.",
        "type": "string"
      },
      "query": {
        "description": "What was said, phrased as a statement (e.g. 'someone offers to help with the\ndishes'), not as a question.",
        "type": "string"
      },
      "top_k": {
        "default": 8,
        "description": "Maximum number of matching results to return.",
        "maximum": 20,
        "minimum": 1,
        "type": "integer"
      }
    },
    "required": [
      "query"
    ],
    "type": "object"
  }
}

{
  "name": "search_facts",
  "description": "Stable semantic facts, induced across clips and kept de-duplicated (keys look like\n\n'P001/identity/name' or 'event:room_tidying/plan'). Three ways in: query for semantic search,\nkey_prefix to enumerate a branch, subject_id for one person. Prefer this over re-reading moments\nwhen the question is about a durable attribute, preference, role or relationship.",
  "inputSchema": {
    "properties": {
      "video_path": {
        "description": "Absolute path to the source video; memory is read from <video_path>.memory/.",
        "type": "string"
      },
      "namespace": {
        "description": "Memory name. Pass video_path too when MEM_LOCAL_DIR is unset; otherwise the\nmemory is read from the configured shared root.",
        "type": "string"
      },
      "query": {
        "description": "Semantic search over fact statements.",
        "type": "string"
      },
      "key_prefix": {
        "description": "List facts whose key starts with this. Keys are built from the canonical NAME,\ne.g. 'Matthew/' for everything known about Matthew, or 'event:' for all events; a\nperson_id like 'P001/' also works and is mapped to that person's name. See\nget_memory_overview for the full key directory.",
        "type": "string"
      },
      "subject_id": {
        "description": "All facts whose subject is this person_id.",
        "type": "string"
      },
      "top_k": {
        "default": 10,
        "description": "Maximum number of matching results to return.",
        "maximum": 20,
        "minimum": 1,
        "type": "integer"
      }
    },
    "type": "object"
  }
}

{
  "name": "search_memory",
  "description": "Hybrid search (dense embeddings + keyword, RRF-fused) across all three containers at once:\n\npeople, semantic facts, and moments. Start here for an open question; narrow down with\nsearch_dialogue / search_facts / get_timeline when you know which kind of evidence you need.",
  "inputSchema": {
    "properties": {
      "video_path": {
        "description": "Absolute path to the source video; memory is read from <video_path>.memory/.",
        "type": "string"
      },
      "namespace": {
        "description": "Memory name. Pass video_path too when MEM_LOCAL_DIR is unset; otherwise the\nmemory is read from the configured shared root.",
        "type": "string"
      },
      "query": {
        "description": "Descriptive statement of what you are looking for, not a question.",
        "type": "string"
      },
      "top_k": {
        "default": 5,
        "description": "Maximum number of matching results to return.",
        "maximum": 20,
        "minimum": 1,
        "type": "integer"
      }
    },
    "required": [
      "query"
    ],
    "type": "object"
  }
}

{
  "name": "watch_and_answer",
  "description": "Watch a SHORT audio-video in one pass and answer from it, with NO memory involved. Use it when\n\nthe video is under ~10 minutes, or when the user has said they do not want a memory built and\njust wants a quick answer. Past ~30 minutes build a memory instead — this tool sends the whole\nvideo in a single request, so it cannot cover a long one no matter how the question is phrased.\nThe video is re-encoded once and that copy is kept, so follow-up questions about the same video\nskip the re-encode. If the video will be asked about several times, a memory is cheaper: build\nit and use plan_and_search. When a watch cannot get through, the result carries\nfallback=\"build_memory\" and the exact command to run. Needs ffmpeg on PATH and an omni endpoint.",
  "inputSchema": {
    "properties": {
      "video_path": {
        "description": "Absolute path to the source video. No memory needs to exist.",
        "type": "string"
      },
      "question": {
        "description": "What to determine from watching the video.",
        "type": "string"
      },
      "model": {
        "description": "Omni model for this call. Leave unset to use the configured default (qwen3.5-omni-\nplus).",
        "type": "string"
      }
    },
    "required": [
      "video_path",
      "question"
    ],
    "type": "object"
  }
}

{
  "name": "happyhorse",
  "description": "Video generation and editing using HappyHorse models. Four modes: (1) text_to_video — generate\n\nvideo from text prompt (happyhorse-1.0-t2v); (2) image_to_video — animate a single image into\nvideo (happyhorse-1.0-i2v); (3) reference_to_video — generate video with 1-9 reference images\nfused as characters/objects (happyhorse-1.0-r2v, use [Image 1] etc. in prompt to reference\nthem); (4) video_edit — edit an existing video with text instruction + optional reference images\n(happyhorse-1.0-video-edit). All modes are async — submit task then poll until completion (1-5\nmin typical).",
  "inputSchema": {
    "properties": {
      "mode": {
        "description": "Operation mode. text_to_video: generate video from text description. image_to_video:\nanimate a single input image (first frame) into video. reference_to_video: generate\nvideo with 1-9 reference images fused into the scene (use [Image 1], [Image 2] etc. in\nprompt to reference each image). video_edit: modify an existing video based on text\ninstruction, optionally guided by reference images.",
        "enum": [
          "text_to_video",
          "image_to_video",
          "reference_to_video",
          "video_edit"
        ],
        "type": "string"
      },
      "prompt": {
        "description": "Text prompt (up to 2500 Chinese chars / 5000 non-Chinese). Required for all modes\nEXCEPT image_to_video (optional there). For reference_to_video: use [Image 1], [Image 2]\netc. to reference images and describe what each depicts, e.g. 'the woman from [Image 1]\nruns on the beach'.",
        "type": "string"
      },
      "image_url": {
        "description": "Input image URL or base64 data for image_to_video mode. Required for\nimage_to_video. This image becomes the first frame of the generated video. Requirements:\nJPEG/JPG/PNG/WEBP, width & height ≥300px, aspect ratio 1:2.5~2.5:1, ≤20MB. Output video\naspect ratio follows the input image (ratio param is ignored).",
        "type": "string"
      },
      "video_url": {
        "description": "Input video URL for video_edit mode. Required for video_edit. Requirements:\nMP4/MOV (H.264), 3-60s duration (>15s auto-truncated to first 15s), long edge ≤4096px,\nshort edge ≥360px, aspect ratio 1:2.5~2.5:1, ≤100MB, >8fps.",
        "type": "string"
      },
      "reference_image_urls": {
        "description": "Reference images for reference_to_video (1-9, required) or video_edit\n(0-5, optional). For reference_to_video: each image provides a character/object to fuse\ninto the video. Prompt must use [Image 1], [Image 2] etc. to reference them by array\norder. For video_edit: style guidance or element replacement reference. Requirements:\nJPEG/JPG/PNG/WEBP, ≤20MB each. r2v: short edge ≥400px, recommend ≥720P. video_edit:\nwidth/height ≥300px.",
        "items": {
          "type": "string"
        },
        "type": "array"
      },
      "resolution": {
        "default": "1080P",
        "description": "Output video resolution. Default: '1080P'.",
        "enum": [
          "720P",
          "1080P"
        ],
        "type": "string"
      },
      "ratio": {
        "default": "16:9",
        "description": "Aspect ratio for text_to_video and reference_to_video modes. Ignored for\nimage_to_video (follows input image) and video_edit. Default: '16:9'.",
        "enum": [
          "16:9",
          "9:16",
          "1:1",
          "4:3",
          "3:4",
          "4:5",
          "5:4",
          "21:9",
          "9:21"
        ],
        "type": "string"
      },
      "duration": {
        "default": 5,
        "description": "Video duration in seconds for text_to_video, image_to_video, and\nreference_to_video modes. Range: 3-15. Default: 5. For video_edit: duration follows\ninput video (≤15s).",
        "type": "integer"
      },
      "audio_setting": {
        "default": "auto",
        "description": "Audio control for video_edit mode only. 'auto': model generates/modifies\naudio. 'origin': preserve original audio from input video. Default: 'auto'.",
        "enum": [
          "auto",
          "origin"
        ],
        "type": "string"
      },
      "seed": {
        "description": "Random seed [0, 2147483647] for reproducibility.",
        "type": "integer"
      },
      "watermark": {
        "default": false,
        "description": "Whether to add watermark. Default: false.",
        "type": "boolean"
      },
      "poll_interval": {
        "default": 15,
        "description": "Polling interval in seconds. Default: 15.",
        "type": "integer"
      },
      "poll_timeout": {
        "default": 600,
        "description": "Max wait time in seconds. Default: 600.",
        "type": "integer"
      },
      "output_dir": {
        "description": "Directory to save generated video. If provided, downloads video to this\ndirectory. If omitted, returns URL only (valid 24h).",
        "type": "string"
      }
    },
    "required": [
      "mode"
    ],
    "type": "object"
  }
}

{
  "name": "minimax_tts",
  "description": "Generate speech with MiniMax from text and a voice ID.\n\nOptional voice, audio, pronunciation, and effect settings have defaults. Returns an MP3\nURL by default; pass output_dir to also save the file locally. Set subtitle_enable=true\nfor an aligned subtitle URL. Requires MINIMAX_API_KEY.",
  "inputSchema": {
    "additionalProperties": false,
    "properties": {
      "text": {
        "description": "Text to synthesize, fewer than 10,000 characters.",
        "maxLength": 9999,
        "pattern": "\\S",
        "type": "string"
      },
      "voice": {
        "description": "MiniMax voice ID, such as English_expressive_narrator.",
        "pattern": "\\S",
        "type": "string"
      },
      "language_type": {
        "default": "Auto",
        "description": "Language hint, e.g. Chinese, English, Japanese, or Auto for detection.",
        "pattern": "\\S",
        "type": "string"
      },
      "output_dir": {
        "description": "Directory to save audio. If omitted, returns a URL valid for 24 hours,\nor saves hex audio to a temporary directory.",
        "type": "string"
      },
      "model": {
        "default": "speech-2.8-hd",
        "description": "MiniMax speech model ID. Defaults to speech-2.8-hd.",
        "pattern": "\\S",
        "type": "string"
      },
      "region": {
        "default": "global",
        "description": "API region matching your MiniMax account: global or cn, independently of\nthe spoken language.",
        "enum": [
          "global",
          "cn"
        ],
        "type": "string"
      },
      "subtitle_enable": {
        "default": false,
        "description": "Also return aligned subtitles as a URL.",
        "type": "boolean"
      },
      "voice_setting": {
        "additionalProperties": false,
        "properties": {
          "speed": {
            "default": 1.0,
            "maximum": 2.0,
            "minimum": 0.5,
            "type": "number"
          },
          "vol": {
            "default": 1.0,
            "exclusiveMinimum": 0,
            "maximum": 10,
            "type": "number"
          },
          "pitch": {
            "default": 0,
            "maximum": 12,
            "minimum": -12,
            "type": "integer"
          },
          "emotion": {
            "enum": [
              "happy",
              "sad",
              "angry",
              "fearful",
              "disgusted",
              "surprised",
              "calm",
              "fluent",
              "whisper"
            ],
            "type": "string"
          }
        },
        "type": "object",
        "default": {
          "speed": 1.0,
          "vol": 1.0,
          "pitch": 0,
          "emotion": null
        },
        "description": "Optional voice controls. speed is a multiplier from 0.5 to 2;\nvol is a multiplier above 0 and up to 10; pitch shifts by -12 to 12 semitones.\nemotion is an optional model-supported emotion. Omitted fields keep their\ndefaults; select the voice with voice, not this object."
      },
      "audio_setting": {
        "additionalProperties": false,
        "properties": {
          "format": {
            "default": "mp3",
            "enum": [
              "mp3",
              "wav",
              "flac",
              "pcm"
            ],
            "type": "string"
          },
          "sample_rate": {
            "default": 32000,
            "enum": [
              8000,
              16000,
              22050,
              24000,
              32000,
              44100
            ],
            "type": "integer"
          },
          "bitrate": {
            "default": 128000,
            "enum": [
              32000,
              64000,
              128000,
              256000
            ],
            "type": "integer"
          },
          "channel": {
            "default": 1,
            "enum": [
              1,
              2
            ],
            "type": "integer"
          }
        },
        "type": "object",
        "default": {
          "format": "mp3",
          "sample_rate": 32000,
          "bitrate": 128000,
          "channel": 1
        },
        "description": "Optional output format, sample_rate in Hz, MP3 bitrate in bits per\nsecond, and channel count. Defaults to MP3, 32 kHz, 128 kbps, mono."
      },
      "pronunciation_dict": {
        "additionalProperties": {
          "items": {
            "type": "string"
          },
          "type": "array"
        },
        "description": "Optional replacements, e.g. {\"tone\": [\"Omg/Oh my god\"]}.",
        "type": "object"
      },
      "voice_modify": {
        "additionalProperties": false,
        "properties": {
          "pitch": {
            "maximum": 100,
            "minimum": -100,
            "type": "integer"
          },
          "intensity": {
            "maximum": 100,
            "minimum": -100,
            "type": "integer"
          },
          "timbre": {
            "maximum": 100,
            "minimum": -100,
            "type": "integer"
          },
          "sound_effects": {
            "enum": [
              "spacious_echo",
              "auditorium_echo",
              "lofi_telephone",
              "robotic"
            ],
            "type": "string"
          }
        },
        "type": "object",
        "description": "Optional pitch, intensity, and timbre effects from -100 to 100,\nplus sound_effects. Disabled by default."
      },
      "stream": {
        "const": false,
        "default": false,
        "description": "Only false is supported; this tool returns non-streaming responses.",
        "type": "boolean"
      },
      "output_format": {
        "default": "url",
        "description": "URL by default; hex responses are decoded and saved locally.",
        "enum": [
          "url",
          "hex"
        ],
        "type": "string"
      }
    },
    "required": [
      "text",
      "voice"
    ],
    "type": "object"
  }
}

{
  "name": "qwen_image",
  "description": "Image generation, editing, and translation using Qwen-Image models. Three modes: (1)\n\ntext_to_image — generate image from text prompt (sync, qwen-image-2.0-pro); (2) image_edit —\nedit an existing image with text instruction, supports up to 3 input images (sync, qwen-\nimage-2.0-pro); (3) image_translate — translate text in an image while preserving layout (async,\nqwen-mt-image). All generated image URLs expire in 24 hours — download promptly.",
  "inputSchema": {
    "properties": {
      "mode": {
        "description": "Operation mode. text_to_image: generate from text prompt only. image_edit: modify\nexisting image(s) with text instruction. image_translate: translate text in image\npreserving layout.",
        "enum": [
          "text_to_image",
          "image_edit",
          "image_translate"
        ],
        "type": "string"
      },
      "prompt": {
        "description": "For text_to_image: image description prompt. For image_edit: editing instruction\n(e.g. 'convert to watercolor style'). Not used for image_translate.",
        "type": "string"
      },
      "image_urls": {
        "description": "Input image URL(s). For image_edit: 1-3 image URLs to edit/combine. For\nimage_translate: exactly 1 image URL. Not used for text_to_image.",
        "items": {
          "type": "string"
        },
        "type": "array"
      },
      "size": {
        "default": "1024*1024",
        "description": "Output image size (width*height). Common options: '1024*1024' (square), '2048*2048'\n(hi-res square), '2688*1536' (16:9 landscape), '1536*2688' (9:16 portrait), '2368*1728'\n(4:3). Total pixels: 512*512 to 2048*2048. Default: '1024*1024'.",
        "type": "string"
      },
      "negative_prompt": {
        "default": "低分辨率，低画质，肢体畸形，画面过饱和",
        "description": "Things to avoid in the generated image. Default: '低分辨率，低画质，肢体畸形，画面过饱和'.\nOnly for text_to_image and image_edit modes.",
        "type": "string"
      },
      "prompt_extend": {
        "default": true,
        "description": "Enable intelligent prompt rewriting for better results. Set to false when you\nneed precise control. Default: true.",
        "type": "boolean"
      },
      "seed": {
        "description": "Random seed for reproducibility. Fix seed while iterating prompts to compare changes.\nOmit for random.",
        "type": "integer"
      },
      "n": {
        "default": 1,
        "description": "Number of images to generate (1-4). Default: 1.",
        "type": "integer"
      },
      "source_lang": {
        "default": "zh",
        "description": "Source language for image_translate mode. Options: zh, en, ja, ko, fr, de, es,\nru, etc. Default: zh.",
        "type": "string"
      },
      "target_lang": {
        "default": "en",
        "description": "Target language for image_translate mode. Options: zh, en, ja, ko, fr, de, es,\nru, etc. Default: en.",
        "type": "string"
      },
      "output_dir": {
        "description": "Directory to save generated images. If provided, downloads images to this\ndirectory. If omitted, returns URLs only (valid 24h).",
        "type": "string"
      }
    },
    "required": [
      "mode"
    ],
    "type": "object"
  }
}

{
  "name": "qwen_tts",
  "description": "Text-to-speech (TTS) using Qwen3-TTS-Flash via the DashScope SDK\n\n(dashscope.MultiModalConversation). Supports 10 languages and 44 system voices. Input: text +\nvoice + language. Output: audio file URL (WAV, 24h validity). Max 512 tokens per call — split\nlong text at sentence boundaries.",
  "inputSchema": {
    "properties": {
      "text": {
        "description": "Text to synthesize into speech. Max ~512 tokens per call. For longer text, split at\nsentence/punctuation boundaries and call multiple times.",
        "type": "string"
      },
      "voice": {
        "default": "Cherry",
        "description": "Voice name. System voices include: Cherry (young female, energetic), Serena (female,\nprofessional), Ethan (male, standard), Chelsie (female, warm), and 40+ others. See\nDashScope docs for full list.",
        "type": "string"
      },
      "language_type": {
        "default": "Auto",
        "description": "Language for synthesis. Options: Chinese, English, Japanese, Korean, French,\nGerman, Spanish, Russian, Portuguese, Auto. Specifying language significantly improves\nquality. Default: Auto.",
        "type": "string"
      },
      "output_dir": {
        "description": "Directory to save the audio file. If provided, downloads the audio to this\ndirectory. If omitted, returns the audio URL only (valid 24h).",
        "type": "string"
      }
    },
    "required": [
      "text"
    ],
    "type": "object"
  }
}

{
  "name": "wan_s2v",
  "description": "Digital human lip-sync video generation using Wan2.2-S2V. Takes a portrait image + audio and\n\ngenerates a talking-head video with lip sync. Two actions: (1) detect — check if an image is\nsuitable for digital human generation (sync and billed per successful request, regardless of\ndetection result); (2) generate — submit image + audio to create lip-sync video (async, billed).\nAlways run detect first before generate. Supports real humans (portrait/half-body/full-body) and\ncartoon characters. Audio max 20s, image must be single person, front-facing, clear.",
  "inputSchema": {
    "properties": {
      "action": {
        "description": "Action to perform. detect: check if image meets requirements (sync and billed per\nsuccessful request; always run first). generate: create lip-sync video from image +\naudio (async, billed, 5-10 min).",
        "enum": [
          "detect",
          "generate"
        ],
        "type": "string"
      },
      "image_url": {
        "description": "Public URL of the portrait image. Requirements: single person, front-facing,\nclear, JPG/JPEG/PNG/BMP/WEBP, resolution 400-7000px per side. Supports: portrait, half-\nbody, full-body, cartoon characters.",
        "type": "string"
      },
      "audio_url": {
        "description": "Public URL of the audio file. Required for 'generate' action only. Requirements:\nWAV or MP3 format, < 15MB, < 20 seconds, must contain clear human voice, remove\nbackground noise/music.",
        "type": "string"
      },
      "resolution": {
        "default": "480P",
        "description": "Output video resolution. Options: '480P' (faster, cheaper) or '720P'. Default:\n'480P'.",
        "enum": [
          "480P",
          "720P"
        ],
        "type": "string"
      },
      "poll_interval": {
        "default": 15,
        "description": "Polling interval in seconds for async generation task. Min 5, recommended 15.\nDefault: 15.",
        "type": "integer"
      },
      "poll_timeout": {
        "default": 700,
        "description": "Max time in seconds to wait for generation to complete. Typical generation\ntime: 5-10 minutes. Default: 700.",
        "type": "integer"
      },
      "output_dir": {
        "description": "Directory to save the generated video. If provided, downloads video to this\ndirectory. If omitted, returns the video URL only (valid 24h).",
        "type": "string"
      }
    },
    "required": [
      "action",
      "image_url"
