{
  "name": "wan_t2v",
  "description": "Video generation using Wan models (wan2.7 series). Supports multiple generation modes: (1)\n\ntext_to_video — generate video from text prompt only (wan2.7-t2v); (2) first_frame — generate\nvideo from a first-frame image + text prompt (wan2.7-i2v); (3) first_last_frame — generate video\nfrom first-frame + last-frame images + text prompt (wan2.7-i2v). Synchronous call via DashScope\nSDK — blocks until video is ready. Typical generation time: 30s-3min depending on duration and\nresolution.",
  "inputSchema": {
    "properties": {
      "mode": {
        "default": "text_to_video",
        "description": "Generation mode. text_to_video: pure text prompt → video (wan2.7-t2v). first_frame:\nimage + text prompt → video starting from that image (wan2.7-i2v). first_last_frame: two\nimages + text prompt → video interpolating between them (wan2.7-i2v).",
        "enum": [
          "text_to_video",
          "first_frame",
          "first_last_frame"
        ],
        "type": "string"
      },
      "prompt": {
        "description": "Video description prompt. Use cinematic language: camera movements (pan, zoom,\ntracking), temporal dynamics (gradually, suddenly, slowly), style keywords (cinematic,\ndocumentary, vintage). Avoid: multi-person interactions, complex gestures, text content.\nRequired for all modes.",
        "type": "string"
      },
      "first_frame_url": {
        "description": "URL of the first frame image. Required for first_frame and first_last_frame\nmodes. Must be a publicly accessible HTTP/HTTPS URL.",
        "type": "string"
      },
      "last_frame_url": {
        "description": "URL of the last frame image. Required for first_last_frame mode only. Must\nbe a publicly accessible HTTP/HTTPS URL.",
        "type": "string"
      },
      "size": {
        "default": "1280*720",
        "description": "Video size preset. For text_to_video this selects the output size; for image-to-video\nit selects only the resolution tier, while aspect ratio and exact dimensions follow the\nfirst frame. Options: '1280*720' (16:9 landscape), '720*1280' (9:16 portrait), '960*960'\n(square), and '1920*1080' (full HD). The legacy '1024*1024' value is accepted and maps\nto Wan 2.7's 960*960 output. Default: '1280*720'.",
        "type": "string"
      },
      "duration": {
        "default": 5,
        "description": "Video duration in seconds. Wan 2.7 accepts 2-15 seconds. Default: 5. Cost scales\nlinearly with duration.",
        "type": "integer"
      },
      "negative_prompt": {
        "default": "",
        "description": "Things to avoid in the video. Example: 'blurry, low quality, distorted\nfaces, watermark'. Default: empty.",
        "type": "string"
      },
      "prompt_extend": {
        "default": true,
        "description": "Enable intelligent prompt rewriting for better video results. Default: true.",
        "type": "boolean"
      },
      "seed": {
        "default": 12345,
        "description": "Random seed for reproducibility [0, 2147483647]. Fix seed to compare prompt\nvariations. Default: 12345.",
        "type": "integer"
      },
      "output_dir": {
        "description": "Directory to save the generated video. If provided, downloads video to this\ndirectory. If omitted, returns the video URL only (valid 24h).",
        "type": "string"
      }
    },
    "required": [
      "prompt"
    ],
    "type": "object"
  }
