{
  "name": "run_fem_analysis",
  "description": "Run the CalculiX solver on an existing Fem::FemAnalysis container and return summary results.\n\nPrerequisites in the document: - A Part-derived solid (e.g. Part::Box, PartDesign::Body) acting\nas the geometry. - A Fem::AnalysisPython container created via `create_object`. - A\nFem::MaterialCommon assigned to the geometry, added to the analysis. - A Fem::FemMeshGmsh\nreferencing the geometry, added to the analysis (the mesh is generated automatically when\ncreated via `create_object`). - At least one Fem::ConstraintFixed and one Fem::ConstraintForce\n(or ConstraintPressure) bound to faces of the geometry, added to the analysis.\n\nA SolverCcxTools is auto-created if the analysis has none.\n\nThe solver runs synchronously on the FreeCAD GUI thread and blocks all other RPC calls for its\nduration; do not fan out parallel requests.\n\nReturns max von Mises stress (MPa), max/min displacement (mm), node count, and the working\ndirectory CalculiX wrote to. On failure, returns the prerequisite-check or solver error along\nwith the working directory for triage.",
  "inputSchema": {
    "properties": {
      "doc_name": {
        "description": "Name of the FreeCAD document.",
        "type": "string"
      },
      "analysis_name": {
        "description": "Name of the Fem::AnalysisPython object.",
        "type": "string"
      },
      "timeout": {
        "default": 600,
        "description": "Seconds to wait for the solver (default 600).",
        "type": "integer"
      }
    },
    "required": [
      "doc_name",
      "analysis_name"
    ],
    "type": "object"
  }
}
